// ─── physicsEngine.test.ts ─────────────────────────────────────────────────────
// Vitest unit tests for Stefan's Law physics engine.
// Run with: npm run test
//
// CRITICAL TEST: The log₁₀(P) vs log₁₀(T) slope from 10 V-I pairs
// generated by computeFilamentState must be in [3.85, 4.15] in ideal mode
// and [3.70, 4.30] with ±1.5% noise across 100 randomised trials.

import { describe, it, expect } from 'vitest';
import {
  computeFilamentState,
  computeLinearRegression,
  computeRg,
  computeR0,
  computeRt,
  computePower,
  computeTemperature,
  computeLogP,
  computeLogT,
  verifyObservation,
  applyNoise,
  getBulbColor,
  computeGlowIntensity,
  computeSigmaEff,
  R0_DEFAULT,
  T_SIM_MIN,
  T_SIM_MAX,
  V_MAX,
  TUNGSTEN_A,
  TUNGSTEN_B,
  R_RATIO_DRAPER,
} from './physicsEngine';

// ─────────────────────────────────────────────────────────────────────────────
describe("Basic formula functions (lab-manual equations)", () => {
  // ── Rg = Vg / Ig ──────────────────────────────────────────────────────────
  it("computeRg: Rg = Vg / Ig", () => {
    expect(computeRg(2.0, 0.5)).toBeCloseTo(4.0);
    expect(computeRg(6.0, 1.0)).toBeCloseTo(6.0);
  });

  it("computeRg: returns 0 when Ig ≤ 0 (zero-guard)", () => {
    expect(computeRg(5, 0)).toBe(0);
    expect(computeRg(5, -1)).toBe(0);
  });

  // ── R₀ = Rg / 3.9 ─────────────────────────────────────────────────────────
  it("computeR0: R0 = Rg / 3.9", () => {
    expect(computeR0(5.85)).toBeCloseTo(5.85 / R_RATIO_DRAPER);
    expect(computeR0(0)).toBe(0);
  });

  it("computeR0: for Rg = R0 × 3.9, roundtrip is consistent", () => {
    const R0 = 1.4;
    const Rg = R0 * R_RATIO_DRAPER;
    expect(computeR0(Rg)).toBeCloseTo(R0, 10);
  });

  // ── Rₜ = V / I ────────────────────────────────────────────────────────────
  it("computeRt: Rt = V / I", () => {
    expect(computeRt(3.0, 0.5)).toBeCloseTo(6.0);
    expect(computeRt(0, 0.5)).toBe(0);
  });

  it("computeRt: returns null when I = 0 (division-by-zero guard)", () => {
    expect(computeRt(5, 0)).toBeNull();
    expect(computeRt(0, 0)).toBeNull();
  });

  // ── P = V × I ─────────────────────────────────────────────────────────────
  it("computePower: P = V × I", () => {
    expect(computePower(3.0, 0.5)).toBeCloseTo(1.5);
    expect(computePower(0, 1)).toBe(0);
    expect(computePower(0, 0)).toBe(0);
  });

  // ── T = 157.12 × (Rₜ/R₀) + 167.33 ───────────────────────────────────────
  it("computeTemperature: at Rt/R0 = 3.9, T ≈ 779 K (consistent with Draper ~800 K)", () => {
    const T = computeTemperature(3.9, 1.0);
    expect(T).toBeCloseTo(TUNGSTEN_A * 3.9 + TUNGSTEN_B);
    // Should be in the ballpark of the Draper point
    expect(T).toBeGreaterThan(700);
    expect(T).toBeLessThan(900);
  });

  it("computeTemperature: at R0 = R0_DEFAULT, T increases with Rt", () => {
    const T1 = computeTemperature(5, R0_DEFAULT);
    const T2 = computeTemperature(10, R0_DEFAULT);
    expect(T2).toBeGreaterThan(T1);
  });

  it("computeTemperature: returns 0 when R0 ≤ 0 (guard)", () => {
    expect(computeTemperature(5, 0)).toBe(0);
  });

  // ── log₁₀ guards ──────────────────────────────────────────────────────────
  it("computeLogP: log10(P) for P > 0", () => {
    expect(computeLogP(1)).toBeCloseTo(0);
    expect(computeLogP(100)).toBeCloseTo(2);
    expect(computeLogP(0.01)).toBeCloseTo(-2);
  });

  it("computeLogP: returns null for P ≤ 0 (log(0) guard)", () => {
    expect(computeLogP(0)).toBeNull();
    expect(computeLogP(-5)).toBeNull();
  });

  it("computeLogT: log10(T) for T > 0", () => {
    expect(computeLogT(1000)).toBeCloseTo(3);
    expect(computeLogT(100)).toBeCloseTo(2);
  });

  it("computeLogT: returns null for T ≤ 0 (guard)", () => {
    expect(computeLogT(0)).toBeNull();
    expect(computeLogT(-100)).toBeNull();
  });
});

// ─────────────────────────────────────────────────────────────────────────────
describe("computeFilamentState — power OFF / slider = 0", () => {
  it("returns zeroed state when power is OFF", () => {
    const s = computeFilamentState(50, false, R0_DEFAULT, false);
    expect(s.V).toBe(0);
    expect(s.I).toBe(0);
    expect(s.P).toBe(0);
    expect(s.logP).toBeNull();
    expect(s.T).toBe(300); // room temperature
  });

  it("returns zeroed state when slider = 0 (even if power ON)", () => {
    const s = computeFilamentState(0, true, R0_DEFAULT, false);
    expect(s.V).toBe(0);
    expect(s.I).toBe(0);
  });

  it("glowIntensity = 0 when power OFF", () => {
    const s = computeFilamentState(0, false, R0_DEFAULT, false);
    expect(s.glowIntensity).toBe(0);
  });
});

// ─────────────────────────────────────────────────────────────────────────────
describe("computeFilamentState — slider active", () => {
  it("V, I, P are all positive when slider > 0 and power ON", () => {
    for (const s of [10, 30, 50, 70, 100]) {
      const st = computeFilamentState(s, true, R0_DEFAULT, false);
      expect(st.V).toBeGreaterThan(0);
      expect(st.I).toBeGreaterThan(0);
      expect(st.P).toBeGreaterThan(0);
    }
  });

  it("V increases monotonically as slider increases", () => {
    const sliders = [5, 20, 40, 60, 80, 100];
    const voltages = sliders.map(s => computeFilamentState(s, true, R0_DEFAULT, false).V);
    for (let i = 1; i < voltages.length; i++) {
      expect(voltages[i]).toBeGreaterThan(voltages[i - 1]);
    }
  });

  it("I increases monotonically as slider increases", () => {
    const sliders = [5, 20, 40, 60, 80, 100];
    const currents = sliders.map(s => computeFilamentState(s, true, R0_DEFAULT, false).I);
    for (let i = 1; i < currents.length; i++) {
      expect(currents[i]).toBeGreaterThan(currents[i - 1]);
    }
  });

  it("T increases monotonically as slider increases", () => {
    const sliders = [5, 20, 40, 60, 80, 100];
    const temps = sliders.map(s => computeFilamentState(s, true, R0_DEFAULT, false).T);
    for (let i = 1; i < temps.length; i++) {
      expect(temps[i]).toBeGreaterThan(temps[i - 1]);
    }
  });

  it(`V at slider=100 is approximately V_MAX (${V_MAX} V)`, () => {
    const s = computeFilamentState(100, true, R0_DEFAULT, false);
    expect(s.V).toBeCloseTo(V_MAX, 1); // within ±0.1 V
  });

  it(`T at slider=100 is T_SIM_MAX = ${T_SIM_MAX} K`, () => {
    const s = computeFilamentState(100, true, R0_DEFAULT, false);
    expect(s.T).toBeCloseTo(T_SIM_MAX, 0);
  });

  it(`T at slider=0.01 is approximately T_SIM_MIN = ${T_SIM_MIN} K`, () => {
    const s = computeFilamentState(0.01, true, R0_DEFAULT, false);
    expect(s.T).toBeGreaterThanOrEqual(T_SIM_MIN);
    expect(s.T).toBeLessThan(T_SIM_MIN + 10);
  });

  it("logP and logT are valid numbers when power is ON and slider > 0", () => {
    const s = computeFilamentState(50, true, R0_DEFAULT, false);
    expect(s.logP).not.toBeNull();
    expect(s.logT).not.toBeNull();
    expect(isFinite(s.logP!)).toBe(true);
    expect(isFinite(s.logT!)).toBe(true);
  });

  it("glowIntensity is in [0, 1] for all slider positions", () => {
    for (const sl of [0, 10, 25, 50, 75, 100]) {
      const s = computeFilamentState(sl, true, R0_DEFAULT, false);
      expect(s.glowIntensity).toBeGreaterThanOrEqual(0);
      expect(s.glowIntensity).toBeLessThanOrEqual(1);
    }
  });
});

// ─────────────────────────────────────────────────────────────────────────────
describe("🔭 CRITICAL: log(P) vs log(T) slope — Stefan's Law verification", () => {
  const SLIDERS = [5, 15, 25, 35, 45, 55, 65, 75, 85, 95, 100];

  it("ideal mode: slope n is in [3.85, 4.15] with R² > 0.9999", () => {
    const points = SLIDERS.map((s) => {
      const st = computeFilamentState(s, true, R0_DEFAULT, false);
      return { x: st.logT!, y: st.logP! };
    });

    const reg = computeLinearRegression(points);
    expect(reg).not.toBeNull();

    console.log(`\n  ── Ideal Mode Regression ──`);
    console.log(`  Slope n   = ${reg!.slope.toFixed(6)}`);
    console.log(`  Intercept = ${reg!.intercept.toFixed(6)}`);
    console.log(`  R²        = ${reg!.r2.toFixed(8)}`);

    expect(reg!.slope).toBeGreaterThan(3.85);
    expect(reg!.slope).toBeLessThan(4.15);
    expect(reg!.r2).toBeGreaterThan(0.9999);
    expect(reg!.verified).toBe(true);
  });

  it("noise mode: slope stays in [3.70, 4.30] across 200 random trials", () => {
    const slopes: number[] = [];

    for (let trial = 0; trial < 200; trial++) {
      const points = SLIDERS.map((s) => {
        const st = computeFilamentState(s, true, R0_DEFAULT, true); // noise ON
        if (st.logP === null || st.logT === null) return null;
        return { x: st.logT, y: st.logP };
      }).filter((p): p is { x: number; y: number } => p !== null);

      const reg = computeLinearRegression(points);
      if (reg) slopes.push(reg.slope);
    }

    const minSlope = Math.min(...slopes);
    const maxSlope = Math.max(...slopes);
    const avgSlope = slopes.reduce((a, b) => a + b, 0) / slopes.length;

    console.log(`\n  ── Noise Mode (200 trials) ──`);
    console.log(`  Min slope = ${minSlope.toFixed(4)}`);
    console.log(`  Max slope = ${maxSlope.toFixed(4)}`);
    console.log(`  Avg slope = ${avgSlope.toFixed(4)}`);

    expect(slopes.length).toBe(200);
    expect(minSlope).toBeGreaterThan(3.70);
    expect(maxSlope).toBeLessThan(4.30);
    // Average should be very close to 4
    expect(avgSlope).toBeGreaterThan(3.90);
    expect(avgSlope).toBeLessThan(4.10);
  });

  it("calibration: σ_eff changes consistently with R0", () => {
    const s1 = computeSigmaEff(1.2);
    const s2 = computeSigmaEff(1.4);
    const s3 = computeSigmaEff(2.2);
    // Higher R0 → higher Rt_max → lower P_max → lower σ_eff
    expect(s1).toBeGreaterThan(s2);
    expect(s2).toBeGreaterThan(s3);
  });
});

// ─────────────────────────────────────────────────────────────────────────────
describe("computeLinearRegression", () => {
  it("returns null for empty array", () => {
    expect(computeLinearRegression([])).toBeNull();
  });

  it("returns null for single point", () => {
    expect(computeLinearRegression([{ x: 1, y: 2 }])).toBeNull();
  });

  it("computes exact slope and intercept for y = 4x + 2", () => {
    const pts = [1, 2, 3, 4, 5].map((x) => ({ x, y: 4 * x + 2 }));
    const reg = computeLinearRegression(pts);
    expect(reg).not.toBeNull();
    expect(reg!.slope).toBeCloseTo(4.0, 10);
    expect(reg!.intercept).toBeCloseTo(2.0, 10);
    expect(reg!.r2).toBeCloseTo(1.0, 10);
  });

  it("verified = true when slope ∈ [3.5, 4.5]", () => {
    const pts = [1, 2, 3].map((x) => ({ x, y: 4 * x }));
    expect(computeLinearRegression(pts)!.verified).toBe(true);
  });

  it("verified = false when slope = 2", () => {
    const pts = [1, 2, 3].map((x) => ({ x, y: 2 * x }));
    expect(computeLinearRegression(pts)!.verified).toBe(false);
  });

  it("handles collinear degenerate case (all same x) gracefully", () => {
    const pts = [{ x: 3, y: 1 }, { x: 3, y: 2 }, { x: 3, y: 3 }];
    expect(computeLinearRegression(pts)).toBeNull();
  });
});

// ─────────────────────────────────────────────────────────────────────────────
describe("verifyObservation — 2% tolerance (student math checker)", () => {
  const V = 3.0, I = 0.2;
  const R0 = R0_DEFAULT;
  const Rt    = V / I;                           // 15
  const P     = V * I;                           // 0.6
  const RtR0  = Rt / R0;
  const T     = TUNGSTEN_A * RtR0 + TUNGSTEN_B;
  const logP  = Math.log10(P);
  const logT  = Math.log10(T);

  it("passes all cells with exact correct values", () => {
    const res = verifyObservation(V, I, R0, {
      Rt:   Rt.toFixed(3),
      P:    P.toFixed(5),
      RtR0: RtR0.toFixed(4),
      T:    T.toFixed(2),
      logP: logP.toFixed(5),
      logT: logT.toFixed(5),
    });
    expect(res.Rt.correct).toBe(true);
    expect(res.P.correct).toBe(true);
    expect(res.RtR0.correct).toBe(true);
    expect(res.T.correct).toBe(true);
    expect(res.logP.correct).toBe(true);
    expect(res.logT.correct).toBe(true);
  });

  it("accepts values within 2% tolerance (calculator rounding)", () => {
    const res = verifyObservation(V, I, R0, {
      Rt:   (Rt * 1.015).toFixed(2),   // 1.5% off — within tolerance
      P:    (P * 0.985).toFixed(4),     // 1.5% off
      RtR0: RtR0.toFixed(2),            // 2-decimal rounding
      T:    T.toFixed(1),               // rounded to 1 decimal
      logP: logP.toFixed(2),            // 2-decimal rounding
      logT: logT.toFixed(2),
    });
    expect(res.Rt.correct).toBe(true);
    expect(res.P.correct).toBe(true);
  });

  it("flags values beyond 2% tolerance as wrong", () => {
    const res = verifyObservation(V, I, R0, {
      Rt:   '10',   // should be 15 — clearly wrong
      P:    '5',    // should be 0.6
      RtR0: '5',
      T:    '500',
      logP: '1',
      logT: '2',
    });
    expect(res.Rt.correct).toBe(false);
    expect(res.P.correct).toBe(false);
    expect(res.RtR0.correct).toBe(false);
    expect(res.T.correct).toBe(false);
    expect(res.logP.correct).toBe(false);
    expect(res.logT.correct).toBe(false);
  });

  it("expected values in result match the physics-engine computed values", () => {
    const res = verifyObservation(V, I, R0, {
      Rt: '', P: '', RtR0: '', T: '', logP: '', logT: '',
    });
    expect(res.Rt.expected).toBeCloseTo(Rt, 5);
    expect(res.P.expected).toBeCloseTo(P, 5);
    expect(res.RtR0.expected).toBeCloseTo(RtR0, 5);
    expect(res.T.expected).toBeCloseTo(T, 2);
    expect(res.logP.expected).not.toBeNull();
    expect(res.logP.expected!).toBeCloseTo(logP, 4);
    expect(res.logT.expected!).toBeCloseTo(logT, 4);
  });

  it("flags empty string as wrong (not crashing)", () => {
    const res = verifyObservation(V, I, R0, {
      Rt: '', P: '', RtR0: '', T: '', logP: '', logT: '',
    });
    expect(res.Rt.correct).toBe(false);
  });

  it("handles I = 0 gracefully (no crash)", () => {
    expect(() =>
      verifyObservation(0, 0, R0, {
        Rt: '', P: '', RtR0: '', T: '', logP: '', logT: '',
      })
    ).not.toThrow();
  });
});

// ─────────────────────────────────────────────────────────────────────────────
describe("applyNoise", () => {
  it("noise stays within ±5% over 1000 samples (3× the stated 1.5%)", () => {
    for (let i = 0; i < 1000; i++) {
      const result = applyNoise(100, 0.015);
      expect(result).toBeGreaterThan(85); // sanity bound
      expect(result).toBeLessThan(115);
    }
  });

  it("mean of 1000 noisy samples is close to original value", () => {
    const samples = Array.from({ length: 1000 }, () => applyNoise(100, 0.015));
    const mean = samples.reduce((a, b) => a + b, 0) / samples.length;
    expect(mean).toBeGreaterThan(99);
    expect(mean).toBeLessThan(101);
  });
});

// ─────────────────────────────────────────────────────────────────────────────
describe("getBulbColor / computeGlowIntensity", () => {
  it("returns dark colour below 600 K", () => {
    expect(getBulbColor(300)).toBe('#1a1208');
    expect(getBulbColor(599)).toBe('#1a1208');
  });

  it("returns non-black colour above 600 K", () => {
    expect(getBulbColor(800)).not.toBe('#1a1208');
    expect(getBulbColor(1500)).not.toBe('#1a1208');
    expect(getBulbColor(2500)).not.toBe('#1a1208');
  });

  it("glowIntensity = 0 at T ≤ 600 K", () => {
    expect(computeGlowIntensity(300)).toBe(0);
    expect(computeGlowIntensity(600)).toBe(0);
  });

  it("glowIntensity = 1 at T ≥ 2600 K", () => {
    expect(computeGlowIntensity(2600)).toBe(1);
    expect(computeGlowIntensity(3000)).toBe(1);
  });

  it("glowIntensity is monotonically increasing between 600–2600 K", () => {
    const temps = [700, 900, 1200, 1600, 2000, 2400];
    const intensities = temps.map(computeGlowIntensity);
    for (let i = 1; i < intensities.length; i++) {
      expect(intensities[i]).toBeGreaterThan(intensities[i - 1]);
    }
  });
});
